(function(E){ const x = E["sales-m1"] = E["sales-m1"] || {units:{}}; x.units["sales-1-3"] = {"grammar":{"id":"c-sales-1-3-g","level":"B1","course":"sales","unit":"sales-1-3","title":"Talking about needs: want you to, need us to","titleTr":"İhtiyaçlar: want you to, need us to","titleFa":"از نیازها حرف بزن: want you to و need us to","formsTable":{"headers":{"en":["Verb","Person","to + verb"],"tr":["Fiil","Kişi","to + fiil"],"fa":["فعل","شخص","to و فعل"]},"rows":[["want","you","to deliver in May"],["would like","us","to send samples first"],["need","the cartons","to arrive on time"],["ask","me","to call after three"]]},"wrong":"We want that you deliver to two warehouses.","right":"We want you to deliver to two warehouses.","blank":{"sentence":"Our shop managers need the nuts ___ fresh for at least six months.","word":"to stay","distractors":["stay","staying"]},"wrong2":"She would like us send samples first.","right2":"She would like us to send samples first.","blank2":{"sentence":"The buyer would like ___ to send two samples first.","word":"us","distractors":["we","that we"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"want / need / would like + person + to + verb.","tr":"want / need / would like + kişi + to + fiil.","fa":"بعد از want، need یا would like اول شخص می‌آید، بعد to و فعل.","ex":"We want you to deliver in May."},{"en":"The person is an object: me, you, him, her, us, them.","tr":"Kişi nesne hâlindedir: me, you, him, her, us, them.","fa":"شخص به شکل مفعولی می‌آید: me، you، him، her، us، them.","ex":"She'd like us to call on Monday."},{"en":"No 'that' after want or would like.","tr":"want ya da would like'tan sonra 'that' yok.","fa":"بعد از want یا would like کلمه‌ی that نمی‌آید.","ex":"We want you to..., not We want that you..."},{"en":"Summarise with the same pattern, so the buyer can correct you.","tr":"Aynı kalıpla özetle, sonra kontrol et; alıcı seni düzeltebilsin.","fa":"با همین الگو خلاصه کن و بعد بپرس درست است یا نه تا خریدار بتواند اصلاحت کند.","ex":"So you'd like us to deliver in May, is that right?"}],"test":{"en":"Is there a person between 'want' and the action? Then write 'to' straight after the person.","tr":"'want' ile eylem arasında bir kişi var mı? O zaman kişiden hemen sonra 'to' yaz.","fa":"بین want و کار، یک شخص هست؟ پس درست بعد از آن شخص to بنویس."},"contrast":{"en":"Turkish says 'teslim etmenizi istiyoruz' and Persian «می‌خواهیم که شما تحویل بدهید», so learners write 'we want that you deliver'. English has no 'that' here: we want you to deliver.","tr":"Türkçede 'teslim etmenizi istiyoruz' deriz; bu yüzden İngilizcede 'we want that you deliver' yazılıyor. İngilizcede burada 'that' yoktur: kişi + to + fiil gelir: we want you to deliver.","fa":"در فارسی می‌گوییم «می‌خواهیم که شما تحویل بدهید»؛ برای همین خیلی از ما می‌نویسیم we want that you deliver. در انگلیسی اینجا that نمی‌آید؛ بعد از want اول شخص می‌آید و بعد to: we want you to deliver."}},"errorWatch":[{"find":["want that you","want that we","wants that you","wants that we","need that you","needs that you","would like that you","would like that we"],"fix":{"en":"No 'that' here: 'We want you to deliver...'.","tr":"Burada 'that' yok: 'We want you to deliver...'.","fa":"اینجا that نمی‌آید: «We want you to deliver...»"}},{"find":["want you deliver","would like us send","wants us deliver","need you send","need us deliver","asked me call","would like you send"],"fix":{"en":"After the person, add to: 'would like us to send'.","tr":"Kişiden sonra to ekle: 'would like us to send'.","fa":"بعد از شخص، to اضافه کن: would like us to send."}}]},"b2":{"id":"c-sales-1-3-b2","level":"B2","track":"B2","course":"sales","unit":"sales-1-3","title":"Summing up: What you need is...","titleTr":"Özetlemek: What you need is...","titleFa":"جمع‌بندی: What you need is...","formsTable":{"headers":{"en":["What + statement","is + the key point"],"tr":["What + düz cümle","is + ana nokta"],"fa":["بخش What (جمله‌ی خبری)","بخش is (نکته‌ی اصلی)"]},"rows":[["What you need","is a supplier who delivers on time."],["What matters most to you","is the cost per kilo."],["What your director wants","is a lower total cost."]]},"wrong":"What do you need is a supplier who delivers on time.","right":"What you need is a supplier who delivers on time.","blank":{"sentence":"What ___ most is the delivery date, not the price per carton.","word":"matters","distractors":["matter","is matter"]},"wrong2":"What your finance director wants it is a lower total cost.","right2":"What your finance director wants is a lower total cost.","blank2":{"sentence":"What the buyer really wants ___ one supplier for all ten shops.","word":"is","distractors":["it is","does"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"What + subject + verb, then is + the key point.","tr":"What + özne + fiil, ardından is + ana nokta.","fa":"اول What بیاور، بعد فاعل و فعل، بعد is و نکته‌ی اصلی.","ex":"What you need is a supplier who delivers on time."},{"en":"The What part is a statement: no do or does.","tr":"What kısmı düz cümledir: do ya da does yok.","fa":"بخش What جمله‌ی خبری است، پس do و does ندارد.","ex":"What you need is..., not What do you need is"},{"en":"No extra 'it' before is.","tr":"is'ten önce fazladan 'it' yok.","fa":"قبل از is کلمه‌ی it اضافه نکن.","ex":"What she wants is..., not What she wants it is"}],"test":{"en":"Read the What part alone. If it sounds like a question, take out do or does.","tr":"What kısmını tek başına oku. Soru gibi duyuluyorsa do ya da does'u çıkar.","fa":"بخش What را تنها بخوان. اگر شبیه سؤال است، do یا does را بردار."},"contrast":{"en":"Turkish ends with the key point naturally ('İhtiyacınız olan şey, zamanında teslim eden bir tedarikçi') and Persian adds «این است که». Learners then add 'it' or a question form. English uses What + statement + is.","tr":"Türkçede ana nokta doğal olarak sonda gelir ('İhtiyacınız olan şey, zamanında teslim eden bir tedarikçi'). Öğrenciler bu yüzden 'it' ya da soru yapısı ekler. İngilizcede What + düz cümle + is kullanılır.","fa":"در فارسی می‌گوییم «چیزی که لازم داری این است که...» و برای همین خیلی از ما it یا ساختار سؤالی اضافه می‌کنیم. در انگلیسی اول What می‌آید، بعد یک جمله‌ی خبری و بعد is."}},"errorWatch":[{"find":["what do you need is","what does he need is","what do you want is","what does she want is"],"fix":{"en":"The What part is a statement: 'What you need is...'.","tr":"What kısmı düz cümledir: 'What you need is...'.","fa":"بخش What جمله‌ی خبری است: «What you need is...»"}},{"find":["wants it is","need it is","needs it is","matters it is"],"fix":{"en":"No extra 'it': 'What he wants is...'.","tr":"Fazladan 'it' yok: 'What he wants is...'.","fa":"it اضافه نکن: «What he wants is...»"}}],"useIn":{"en":"B2: sum up the customer's needs once with 'What you need is...' or 'What matters most to you is...'.","tr":"B2: müşterinin ihtiyaçlarını bir kez 'What you need is...' ya da 'What matters most to you is...' ile özetle.","fa":"مسیر B2: نیازهای مشتری را یک بار با What you need is... یا What matters most to you is... جمع‌بندی کن."},"exitItem":{"from":"sales-1-3","kind":"blank","prompt":"What the shops ___ is a carton that stacks safely.","options":["needs to","are needing","need"],"correct":2}},"vocab":{"id":"c-sales-1-3-v","level":"B1","category":"vocab","course":"sales","unit":"sales-1-3","goals":["career"],"title":{"en":"Needs and buyers","tr":"İhtiyaçlar ve alıcılar","fa":"نیازها و خریدارها"},"cards":[{"word":"requirement","sentence":"A fixed delivery date is his main requirement.","meaning":{"en":"Something a customer must have.","tr":"gereklilik, şart.","fa":"نیاز اصلی؛ شرط"}},{"word":"volume","sentence":"What volume of saffron do you buy each year?","meaning":{"en":"How much or how many.","tr":"hacim, miktar.","fa":"حجم؛ مقدار"}},{"word":"deliver","sentence":"Can you deliver to two warehouses?","meaning":{"en":"To bring goods to a place.","tr":"teslim etmek.","fa":"تحویل دادن"}},{"word":"warehouse","sentence":"Their warehouse is near the port.","meaning":{"en":"A large building where goods are kept.","tr":"depo.","fa":"انبار"}},{"word":"reorder","sentence":"The shops reorder every month.","meaning":{"en":"To buy the same thing again.","tr":"yeniden sipariş vermek","fa":"دوباره سفارش دادن"}},{"word":"stock","sentence":"We keep two months of stock in the warehouse.","meaning":{"en":"Goods you keep ready to sell.","tr":"stok","fa":"موجودی انبار"}},{"word":"summarise","sentence":"Let me summarise what you need.","meaning":{"en":"To say the main points again in a few words.","tr":"özetlemek.","fa":"خلاصه کردن"}},{"word":"open question","sentence":"An open question starts with what, how or why.","meaning":{"en":"A question that needs more than yes or no.","tr":"açık uçlu soru.","fa":"سؤال باز؛ سؤالی که جوابش فقط بله یا نه نیست"}},{"word":"budget","sentence":"What is your budget for packaging this year?","meaning":{"en":"The money a company plans to spend.","tr":"bütçe.","fa":"بودجه"}},{"word":"decision maker","sentence":"Is the owner the only decision maker?","meaning":{"en":"The person who can say yes to a purchase.","tr":"karar verici.","fa":"تصمیم‌گیرنده"}}]},"judge":{"id":"c-sales-1-3-j","course":"sales","unit":"sales-1-3","type":"judge","title":{"en":"A good question, or a sales speech?","tr":"İyi bir soru mu, satış konuşması mı?","fa":"سؤال خوب یا سخنرانی فروش؟"},"prompt":"A buyer of machine parts says: \"Our current supplier is often late.\" Four replies.","parts":["Finds the problem","Open question","Checks understanding"],"instruction":{"en":"Tap what each reply does. The best reply does all three.","tr":"Her cevabın ne yaptığına dokun. En iyi cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. بهترین جواب هر سه را دارد."},"items":[{"by":"New rep","answer":"We are never late! We have 15 years of experience and a modern factory.","present":[],"fix":{"en":"A speech, and a promise too early. Ask about the problem first: 'How late, and what does that cost you?'","tr":"Bu bir konuşma ve çok erken bir söz. Önce sorunu sor: 'How late, and what does that cost you?'","fa":"این سخنرانی است و زود هم قول می‌دهد. اول از مشکل بپرس: «How late, and what does that cost you?»"}},{"by":"Sales rep","answer":"Is that a problem?","present":["Finds the problem"],"fix":{"en":"Right topic, but a yes or no gets you nothing. Open it: 'What happens when the parts come late?'","tr":"Konu doğru ama evet ya da hayır sana bilgi vermez. Soruyu aç: 'What happens when the parts come late?'","fa":"موضوع درست است، ولی جواب بله یا نه چیزی به تو نمی‌دهد. سؤال را باز کن: «What happens when the parts come late?»"}},{"by":"AI tool","answer":"Could you share more about your overall supply chain strategy and your vision for the future?","present":["Open question"],"fix":{"en":"Open, but too big and far from what the buyer just said. Ask about the late parts.","tr":"Açık ama çok geniş ve alıcının az önce söylediğinden uzak. Geciken parçaları sor.","fa":"باز است، ولی خیلی کلی است و از حرف خریدار دور می‌افتد. درباره‌ی قطعه‌هایی بپرس که دیر رسیده‌اند."}},{"by":"Good model","answer":"So deliveries are often late. What happens on your line when parts come a week late, and have I understood that correctly?","present":["Finds the problem","Open question","Checks understanding"],"fix":null}]},"speaking":{"id":"sales-1-3","course":"sales","unit":"sales-1-3","topic":{"en":"The needs call","tr":"İhtiyaç görüşmesi","fa":"تماس شناخت نیاز"},"warmup":{"en":"What do you always want to know before you buy something big for work?","tr":"İş için büyük bir şey almadan önce her zaman ne bilmek istersin?","fa":"قبل از یک خرید بزرگ برای کار، همیشه دوست داری چه چیزی را بدانی؟"},"questions":[{"en":"Prepare and ask four questions for a buyer: facts, problem, cost, better.","tr":"Bir alıcı için dört soru hazırla ve sor: gerçekler, sorun, maliyet, daha iyisi.","fa":"برای یک خریدار چهار سؤال آماده کن و بپرس: واقعیت، مشکل، هزینه، نتیجه‌ی بهتر."},{"en":"The buyer says: 'We need 300 kilos a month, and the last two deliveries were late, so our shops ran out.' Summarise it and check.","tr":"Alıcı diyor ki: 'We need 300 kilos a month, and the last two deliveries were late, so our shops ran out.' Özetle ve kontrol et.","fa":"خریدار می‌گوید: «We need 300 kilos a month, and the last two deliveries were late, so our shops ran out.» خلاصه کن و بپرس درست فهمیده‌ای یا نه."},{"en":"Ask who else decides, and what the next step is.","tr":"Başka kimin karar verdiğini ve sonraki adımın ne olduğunu sor.","fa":"بپرس چه کس دیگری تصمیم می‌گیرد و قدم بعدی چیست."}],"followups":[{"en":"Now write down the four questions you would ask a real buyer of your product.","tr":"Şimdi ürününün gerçek bir alıcısına soracağın dört soruyu yaz.","fa":"حالا چهار سؤالی را که از یک خریدار واقعی محصولت می‌پرسی بنویس."}],"expressions":[{"phrase":"What happens when ...?","meaning":{"en":"Finds what a problem costs.","tr":"Bir sorunun neye mal olduğunu bulur.","fa":"هزینه‌ی یک مشکل را روشن می‌کند."}},{"phrase":"So what you need is ...","meaning":{"en":"Summarises the need.","tr":"İhtiyacı özetler.","fa":"نیاز را خلاصه می‌کند."}},{"phrase":"Have I understood that correctly?","meaning":{"en":"Checks your summary.","tr":"Özetini kontrol eder.","fa":"درستی خلاصه‌ات را بررسی می‌کند."}}],"model":"Thanks for your time. How much do you buy a month? And what goes wrong with deliveries today? I see. What happens in your shops when a delivery is late? So you'd like us to deliver 300 kilos a month, on a fixed date, because empty shelves cost you sales. Have I understood that correctly? Who else decides on a new supplier?","selfCheck":[{"en":"I asked more about problems than about facts.","tr":"Gerçeklerden çok sorunları sordum.","fa":"بیشتر از واقعیت‌ها درباره‌ی مشکل‌ها پرسیدم."},{"en":"I asked one question at a time.","tr":"Bir seferde tek soru sordum.","fa":"هر بار یک سؤال پرسیدم."},{"en":"I summarised using the buyer's numbers.","tr":"Alıcının rakamlarıyla özetledim.","fa":"با عددهای خود خریدار خلاصه کردم."},{"en":"I asked who else decides.","tr":"Başka kimin karar verdiğini sordum.","fa":"پرسیدم چه کس دیگری تصمیم می‌گیرد."}]},"writing":{"id":"c-sales-1-3-w","course":"sales","unit":"sales-1-3","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your needs sheet","tr":"İhtiyaç sayfan","fa":"برگه‌ی شناخت نیاز تو"},"portfolio":"sales-final-2","prompt":{"en":"Write for your own product, or for a buyer of packaging film whose last supplier was late (the buyer needs 20 rolls a month, a fixed delivery date and film that doesn't tear, and wants a test roll first). Part 1: your four questions (facts, problem, cost, better). Part 2: a short email after the call (50-70 words): thank the buyer, summarise three needs, say what you will send and by when.","tr":"Kendi ürünün için ya da son tedarikçisi geciken bir ambalaj filmi alıcısı için yaz (alıcının ihtiyacı: ayda 20 rulo, sabit teslim tarihi ve yırtılmayan film; önce bir deneme rulosu istiyor). 1. kısım: soracağın dört soru (gerçekler, sorun, maliyet, daha iyisi). 2. kısım: görüşmeden sonra kısa bir e-posta (50-70 kelime): alıcıya teşekkür et, üç ihtiyacı özetle, ne göndereceğini ve ne zamana kadar göndereceğini söyle.","fa":"برای محصول خودت، یا برای خریدار فیلم بسته‌بندی که تأمین‌کننده‌ی قبلی‌اش دیر تحویل داده، بنویس (این خریدار ماهی ۲۰ رول می‌خواهد با تاریخ تحویل ثابت و فیلمی که پاره نشود؛ اول هم یک رول آزمایشی می‌خواهد). بخش ۱: چهار سؤالت (واقعیت، مشکل، هزینه، نتیجه‌ی بهتر). بخش ۲: یک ایمیل کوتاه بعد از تماس (۵۰ تا ۷۰ کلمه): از خریدار تشکر کن، سه نیاز را خلاصه کن و بگو چه چیزی را تا کی می‌فرستی."},"model":"Questions: How much film do you use a month? What goes wrong with deliveries today? What happens when film arrives late? What would change with a fixed delivery date?\n\nDear Ms Rossi,\n\nThank you for your time today. You told me that you need three things: 20 rolls a month, a fixed delivery date, and film that doesn't tear on your machines. You would like us to send a test roll first. I will send it by Friday.\n\nBest regards","frame":"Questions: How much ___? What goes wrong ___? What happens when ___? What would change ___?\n\nDear ___,\n\nThank you for ___. You told me that you need three things: ___, ___ and ___. You would like us to ___. I will send ___ by ___.\n\nBest regards","words":[{"word":"What happens when"},{"word":"You would like us to"},{"word":"by Friday"}],"minWords":60,"minSentences":5,"rubric":["Task done: four questions, three needs, what you will send and when","Organised: questions, then thanks, summary and next step","Language: would like us to + verb; open questions","Tone: the buyer's words and numbers, not your sales talk"],"rubricI18n":{"tr":["Görev: dört soru, üç ihtiyaç, ne gönderileceği ve ne zaman","Düzen: sorular, sonra teşekkür, özet ve sonraki adım","Dil: would like us to + fiil; açık sorular","Üslup: satış konuşman değil, alıcının sözleri ve rakamları"],"fa":["کامل بودن کار: چهار سؤال، سه نیاز، چیزی که می‌فرستی و زمانش","نظم: سؤال‌ها، بعد تشکر، خلاصه و قدم بعدی","زبان: would like us to با فعل ساده؛ سؤال‌های باز","لحن: کلمه‌ها و عددهای خریدار، نه حرف‌های فروش تو"]}},"exit":{"id":"c-sales-1-3-x","course":"sales","unit":"sales-1-3","type":"exit","items":[{"from":"sales-1-3","kind":"blank","prompt":"The shops want us ___ before the holidays.","options":["to deliver","deliver","delivering"],"correct":0,"point":2},{"from":"sales-1-3","kind":"mcq","prompt":"Which question finds what a problem costs?","options":["How old is your company, and who runs it?","What happens when the parts arrive late?","Do you like our catalogue and our website?"],"correct":1,"point":1},{"from":"sales-1-3","kind":"mcq","prompt":"Which line summarises a buyer's need?","options":["We have twelve colours and three sizes for you to choose from.","Our factory is in Izmir, and we ship all over Europe every week.","So you need the goods to arrive before June, is that right?"],"correct":2,"point":1},{"from":"sales-1-2","kind":"blank","prompt":"Do you know when the new catalogue ___ ready?","options":["will be","will it be","is it"],"correct":0},{"from":"sales-1-2","kind":"mcq","prompt":"What is the one job of a first email?","options":["To get a second contact","To explain your whole range","To send your full price list"],"correct":0},{"from":"sales-1-1","kind":"mcq","prompt":"\"Each batch has a lab report\" is an example of ___.","options":["a next step","a proof","a brand"],"correct":1}]},"explain":{"id":"c-sales-1-3-e","course":"sales","unit":"sales-1-3","type":"explain","level":"B1","title":{"en":"Find the need before you offer","tr":"Teklif etmeden önce ihtiyacı bul","fa":"قبل از پیشنهاد، نیاز را پیدا کن"},"objective":{"en":"In this lesson you will learn to ask questions that find a buyer's real need, listen, and summarise it back.","tr":"Bu derste alıcının gerçek ihtiyacını ortaya çıkaran sorular sormayı, dinlemeyi ve duyduğunu özetlemeyi öğreneceksin.","fa":"در این درس یاد می‌گیری سؤال‌هایی بپرسی که نیاز واقعی خریدار را روشن کنند، گوش بدهی و آن را خلاصه کنی و به خودش بگویی."},"hook":{"en":"Find out what the buyer needs before you offer anything. If you offer first, you are guessing, and a wrong guess sounds like a sales speech.","tr":"Bir şey teklif etmeden önce alıcının neye ihtiyacı olduğunu öğren. Önce teklif edersen tahmin yürütürsün; yanlış tahmin de satış konuşması gibi duyulur.","fa":"قبل از اینکه چیزی پیشنهاد بدهی، بفهم خریدار چه نیازی دارد. اگر اول پیشنهاد بدهی حدس می‌زنی و حدس غلط شبیه سخنرانی فروش است."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Four kinds of question, in order","tr":"Sırayla dört tür soru","fa":"چهار نوع سؤال، به ترتیب"},"steps":[{"en":"Facts: ask only what you can't find online. Otherwise you waste their time.","tr":"Gerçekler: yalnızca internette bulamayacağın şeyleri sor. Yoksa zamanlarını boşa harcarsın.","fa":"واقعیت‌ها: فقط چیزی را بپرس که در اینترنت پیدا نمی‌شود. وگرنه وقتشان را هدر می‌دهی.","ex":"How many cartons do you buy a month?"},{"en":"Problem: ask what isn't working today. A buyer changes supplier only to fix something.","tr":"Sorun: bugün neyin yolunda gitmediğini sor. Alıcı tedarikçiyi ancak bir şeyi düzeltmek için değiştirir.","fa":"مشکل: بپرس امروز چه چیزی درست کار نمی‌کند. خریدار فقط برای حل یک مشکل تأمین‌کننده‌اش را عوض می‌کند.","ex":"What goes wrong with your current deliveries?"},{"en":"Cost: ask what that problem costs them. A costly problem is worth paying to solve.","tr":"Maliyet: bu sorunun onlara neye mal olduğunu sor. Pahalı bir sorunu çözmek için para ödemeye değer.","fa":"هزینه: بپرس این مشکل چقدر برایشان خرج دارد. برای حل مشکل پرهزینه می‌ارزد پول بدهند.","ex":"What happens when a delivery is a week late?"},{"en":"Better: ask what a good result would look like. Now they describe what you should offer.","tr":"Daha iyisi: iyi bir sonucun nasıl görüneceğini sor. Böylece ne teklif etmen gerektiğini kendileri anlatır.","fa":"نتیجه‌ی بهتر: بپرس از نظرشان نتیجه‌ی خوب چیست. این‌طوری خودشان می‌گویند چه چیزی پیشنهاد بدهی.","ex":"What would change if deliveries came on time?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Talking about needs: want you to, need us to","tr":"İhtiyaçlar: want you to, need us to","fa":"از نیازها حرف بزن: want you to و need us to"},"steps":[{"en":"want / need / would like + person + to + verb.","tr":"want / need / would like + kişi + to + fiil.","fa":"بعد از want، need یا would like اول شخص می‌آید، بعد to و فعل.","ex":"We want you to deliver in May."},{"en":"The person is an object: me, you, him, her, us, them.","tr":"Kişi nesne hâlindedir: me, you, him, her, us, them.","fa":"شخص به شکل مفعولی می‌آید: me، you، him، her، us، them.","ex":"She'd like us to call on Monday."},{"en":"No 'that' after want or would like.","tr":"want ya da would like'tan sonra 'that' yok.","fa":"بعد از want یا would like کلمه‌ی that نمی‌آید.","ex":"We want you to..., not We want that you..."},{"en":"Summarise with the same pattern, so the buyer can correct you.","tr":"Aynı kalıpla özetle, sonra kontrol et; alıcı seni düzeltebilsin.","fa":"با همین الگو خلاصه کن و بعد بپرس درست است یا نه تا خریدار بتواند اصلاحت کند.","ex":"So you'd like us to deliver in May, is that right?"}],"table":{"headers":{"en":["Verb","Person","to + verb"],"tr":["Fiil","Kişi","to + fiil"],"fa":["فعل","شخص","to و فعل"]},"rows":[["want","you","to deliver in May"],["would like","us","to send samples first"],["need","the cartons","to arrive on time"],["ask","me","to call after three"]]},"tip":{"en":"Turkish says 'teslim etmenizi istiyoruz' and Persian «می‌خواهیم که شما تحویل بدهید», so learners write 'we want that you deliver'. English has no 'that' here: we want you to deliver.","tr":"Türkçede 'teslim etmenizi istiyoruz' deriz; bu yüzden İngilizcede 'we want that you deliver' yazılıyor. İngilizcede burada 'that' yoktur: kişi + to + fiil gelir: we want you to deliver.","fa":"در فارسی می‌گوییم «می‌خواهیم که شما تحویل بدهید»؛ برای همین خیلی از ما می‌نویسیم we want that you deliver. در انگلیسی اینجا that نمی‌آید؛ بعد از want اول شخص می‌آید و بعد to: we want you to deliver."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Who else decides?","tr":"Başka kim karar veriyor?","fa":"چه کس دیگری تصمیم می‌گیرد؟"},"body":{"en":"Listen more than you talk, and take notes. Spread your questions through the call, not all at the start. Before the end, ask who else decides and what happens next. Many deals stop because the seller only spoke to one person.","tr":"Konuştuğundan çok dinle ve not al. Sorularının hepsini başta değil, görüşmeye yayarak sor. Bitirmeden önce başka kimin karar verdiğini ve sonra ne olacağını sor. Birçok satış, satıcı tek kişiyle konuştuğu için durur.","fa":"بیشتر از حرف زدن گوش بده و یادداشت بردار. سؤال‌هایت را در طول تماس پخش کن، نه همه را اول کار. قبل از پایان بپرس چه کس دیگری تصمیم می‌گیرد و قدم بعدی چیست. خیلی از معامله‌ها می‌خوابند چون فروشنده فقط با یک نفر حرف زده است."},"phrases":[{"phrase":"What happens when ...?","meaning":{"en":"Finds what a problem costs.","tr":"Bir sorunun neye mal olduğunu bulur.","fa":"هزینه‌ی یک مشکل را روشن می‌کند."}},{"phrase":"So what you need is ...","meaning":{"en":"Summarises the need.","tr":"İhtiyacı özetler.","fa":"نیاز را خلاصه می‌کند."}},{"phrase":"Have I understood that correctly?","meaning":{"en":"Checks your summary.","tr":"Özetini kontrol eder.","fa":"درستی خلاصه‌ات را بررسی می‌کند."}},{"phrase":"decision maker","meaning":{"en":"The person who can say yes to a purchase.","tr":"karar verici.","fa":"تصمیم‌گیرنده"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Summarise before you offer","tr":"Teklif etmeden önce özetle","fa":"قبل از پیشنهاد، خلاصه کن"},"item":"The buyer said: We need 200 cartons a month, on time, because a late delivery leaves our shelves empty. Your reply: Great, we have a very good product for that. Let me tell you about our factory.","answer":"So you need 200 cartons a month, on time, because a late delivery leaves your shelves empty. Is that right?","walk":[{"en":"Don't answer with a speech. Give back what you heard.","tr":"Bir konuşmayla cevap verme. Duyduğunu geri söyle.","fa":"با سخنرانی جواب نده. چیزی را که شنیدی به خودشان بگو."},{"en":"Use their numbers and their words, not yours.","tr":"Senin değil, onların rakamlarını ve sözlerini kullan.","fa":"عددها و کلمه‌های خودشان را به کار ببر، نه کلمه‌های خودت را."},{"en":"End with a check. They will correct you, and that helps.","tr":"Bir kontrolle bitir. Seni düzeltirler ve bu işe yarar.","fa":"در آخر بپرس درست فهمیده‌ای یا نه. اگر اشتباه کرده باشی اصلاحت می‌کنند و این به نفع توست."}]},"quick":{"prompt":"Before you offer anything, first ___ what the buyer told you.","options":["summarise","forget","repeat the price of"],"correct":0,"why":{"en":"summarise: it proves you listened, and the buyer can correct any mistake before you quote.","tr":"summarise: dinlediğini gösterir ve alıcı, sen teklif vermeden önce hatayı düzeltebilir.","fa":"جواب summarise است، چون نشان می‌دهد گوش داده‌ای و خریدار می‌تواند قبل از پیشنهاد قیمت اشتباه را درست کند."}},"remember":{"en":"Ask one question at a time, then stop talking. You can now find a buyer's real need and check it with a one-line summary.","tr":"Bir seferde tek soru sor, sonra sus. Artık alıcının gerçek ihtiyacını bulabilir ve tek satırlık bir özetle doğrulayabilirsin.","fa":"هر بار یک سؤال بپرس و بعد دیگر حرف نزن. حالا می‌توانی نیاز واقعی خریدار را پیدا کنی و با یک خلاصه‌ی یک‌خطی مطمئن شوی درست فهمیده‌ای."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Summing up: What you need is...","tr":"Özetlemek: What you need is...","fa":"جمع‌بندی: What you need is..."},"steps":[{"en":"What + subject + verb, then is + the key point.","tr":"What + özne + fiil, ardından is + ana nokta.","fa":"اول What بیاور، بعد فاعل و فعل، بعد is و نکته‌ی اصلی.","ex":"What you need is a supplier who delivers on time."},{"en":"The What part is a statement: no do or does.","tr":"What kısmı düz cümledir: do ya da does yok.","fa":"بخش What جمله‌ی خبری است، پس do و does ندارد.","ex":"What you need is..., not What do you need is"},{"en":"No extra 'it' before is.","tr":"is'ten önce fazladan 'it' yok.","fa":"قبل از is کلمه‌ی it اضافه نکن.","ex":"What she wants is..., not What she wants it is"}],"table":{"headers":{"en":["What + statement","is + the key point"],"tr":["What + düz cümle","is + ana nokta"],"fa":["بخش What (جمله‌ی خبری)","بخش is (نکته‌ی اصلی)"]},"rows":[["What you need","is a supplier who delivers on time."],["What matters most to you","is the cost per kilo."],["What your director wants","is a lower total cost."]]},"body":{"en":"B2: sum up the customer's needs once with 'What you need is...' or 'What matters most to you is...'.","tr":"B2: müşterinin ihtiyaçlarını bir kez 'What you need is...' ya da 'What matters most to you is...' ile özetle.","fa":"مسیر B2: نیازهای مشتری را یک بار با What you need is... یا What matters most to you is... جمع‌بندی کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
